import java.util.*;
import java.io.*;

public class Main {
    static final int MAX = 270005;
    static int n, m, k, mod;
    static int[][] f = new int[19][MAX];
    static List<Long> g;
    static int[] bit_count = new int[MAX];
    static int[] factorial = new int[MAX];
    static int[] inv_factorial = new int[MAX];

    static int adjust(int x) {
        if (x < 0) return x + mod;
        if (x >= mod) return x - mod;
        return x;
    }

    static void update_value(int[] arr, int index, int y) {
        arr[index] = adjust(arr[index] + y);
    }

    static int bin_pow(int base, int exp) {
        int res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (int)((long)res * base % mod);
            base = (int)((long)base * base % mod);
            exp >>= 1;
        }
        return res;
    }

    static void precompute_factorials(int n) {
        factorial[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorial[i] = (int)((long)factorial[i - 1] * i % mod);
        }
        inv_factorial[n] = bin_pow(factorial[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) {
            inv_factorial[i] = (int)((long)inv_factorial[i + 1] * (i + 1) % mod);
        }
    }

    static void transform_array(int[] arr, int size, int h) {
        for (int p = 1; p < size; p <<= 1) {
            for (int i = 0; i < size; i += p << 1) {
                for (int k = i; k < i + p; k++) {
                    int val = arr[k + p];
                    int updateVal = (int)((long)h * arr[k] % mod);
                    arr[k + p] = adjust(val + updateVal);
                }
            }
        }
    }

    static List<Long> multiplySeries(List<Long> A, List<Long> B, int l) {
        List<Long> C = new ArrayList<>(Collections.nCopies(l + 1, 0L));
        for (int i = 0; i <= l; i++) {
            for (int j = 0; j <= l - i; j++) {
                long val = C.get(i + j) + A.get(i) * B.get(j);
                C.set(i + j, val % mod);
            }
        }
        return C;
    }

    static List<Long> powerSeries(List<Long> A, int k, int l) {
        List<Long> C = new ArrayList<>(Collections.nCopies(l + 1, 0L));
        C.set(0, 1L);
        List<Long> base = new ArrayList<>(A);
        while (k > 0) {
            if ((k & 1) == 1) {
                C = multiplySeries(C, base, l);
            }
            base = multiplySeries(base, base, l);
            k >>= 1;
        }
        return C;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());
        mod = Integer.parseInt(st.nextToken());

        precompute_factorials(n);
        if ((n & 1) == 1) {
            System.out.println(bin_pow(k, n));
            return;
        }

        m = 1;
        while (m <= n) m <<= 1;
        int l = 0;
        int tempM = m;
        while (tempM > 1) {
            tempM >>= 1;
            l++;
        }

        for (int i = 0; i < m; i++) {
            bit_count[i] = Integer.bitCount(i);
        }

        precompute_factorials(m);
        for (int i = 0; i < m; i++) {
            f[bit_count[i]][i] = inv_factorial[i];
        }

        for (int i = 0; i < l; i++) {
            transform_array(f[i], m, 1);
        }

        g = new ArrayList<>(Collections.nCopies(l + 1, 0L));
        for (int s = 0; s < m; s++) {
            for (int i = 0; i <= l; i++) {
                g.set(i, (long)f[i][s]);
            }
            g = powerSeries(g, k, l);
            for (int i = 0; i <= l; i++) {
                f[i][s] = g.get(i).intValue();
            }
        }

        transform_array(f[bit_count[n]], m, -1);
        long result = adjust((int)((long)bin_pow(k, n) - (long)f[bit_count[n]][n] * factorial[n] % mod));
        System.out.println(result);
    }
}

